#include "DisplayProtocol.h"
#include "DisplayScroll.h"
#include <assert.h>
#include <stdio.h>
static bool parse(const char *s,DisplayFrame &f){char line[2048];strncpy(line,s,sizeof line);line[sizeof line-1]=0;return parseDisplayFrame(line,f);}
int main(){DisplayFrame f;assert(parse("P5\t1\t1794170000\t3600\t1\tplay\t7%20%2F%2019\tGr%C3%BC%C3%9Fe%20%26%20Musik\tBj%C3%B6rk",f));assert(!strcmp(f.track,"7 / 19"));assert(!strcmp(f.title,"Grüße & Musik"));assert(!strcmp(f.artist,"Björk"));assert(f.offset==3600&&f.validTime);assert(!parse("P5\t2\t1794170000\t999999\t1\tplay\t1\ta\tb",f));assert(f.sequence==1);assert(!parse("P5\t2\t1794170000\t3600\t1\tplay\t1\tbad%00x\tartist",f));assert(!parse("P5\t2\t1794170000\t3600\t1\tplay\t1\tbad%GG\tartist",f));assert(!parse("P5\t2\t1794170000\t3600\t1\tplay\t1\ta\tb\textra",f));assert(!parse("P5\t2\t1",f));bool on=true;uint8_t brightness=100;char control[]="P5D\t0\t10";assert(parseDisplayControl(control,on,brightness)&&!on&&brightness==10);char bad[]="P5D\t1\t101";assert(!parseDisplayControl(bad,on,brightness)&&!on&&brightness==10);char extra[]="P5D\t1\t20\textra";assert(!parseDisplayControl(extra,on,brightness));assert(parse("P5\t9\t1794170000\t3600\t1\tradio\tWDR%202%20Rheinland%20aktuell%2C%20Westdeutscher%20Rundfunk%20Koeln\tChildren\tRobert%20Miles",f));assert(!strcmp(f.mode,"radio")&&strlen(f.track)>40&&!strcmp(f.title,"Children"));assert(displayScrollOffset(400,188,1800,true)==0);assert(displayScrollOffset(400,188,1860,true)==1);assert(displayScrollOffset(400,188,1800+436*60,true)==0);assert(displayScrollOffset(400,188,100000,true)==0);assert(displayScrollOffset(100,188,99999,true)==0);assert(!displayStandby(f));assert(parse("P5\t10\t1794170000\t3600\t1\toff\tWDR\tSong\tArtist",f)&&displayStandby(f));puts("Firmware protocol: UTF-8 roundtrip, bounds, malformed input and state preservation OK");}
